<?php

use App\Models\Branch;
use App\Models\Product;
use App\Models\ProductWarehouse;
use App\Models\Tenant;
use App\Models\Warehouse;
use Illuminate\Foundation\Testing\RefreshDatabase;
use Tests\TestCase;

uses(TestCase::class, RefreshDatabase::class);

test('warehouse has relationships with branch and products with stock pivot', function () {
    $tenant = Tenant::factory()->create();
    // Default branch and warehouse auto-generated by TenantObserver
    $branch = $tenant->branches()->first();
    $warehouse = $tenant->warehouses()->first();

    $product = Product::create([
        'tenant_id' => $tenant->id,
        'name' => 'Resma Chambril A4',
        'sku' => 'RES-A4-75',
        'price' => 5000,
        'cost_price' => 3000,
        'stock' => 100,
        'min_stock' => 10,
    ]);

    ProductWarehouse::create([
        'tenant_id' => $tenant->id,
        'product_id' => $product->id,
        'warehouse_id' => $warehouse->id,
        'stock' => 60,
        'min_stock' => 10,
        'aisle_location' => 'Estante A-1',
    ]);

    $warehouse2 = Warehouse::create([
        'tenant_id' => $tenant->id,
        'branch_id' => $branch->id,
        'name' => 'Depósito Secundario',
        'code' => 'DEP-02',
        'is_default' => false,
    ]);

    ProductWarehouse::create([
        'tenant_id' => $tenant->id,
        'product_id' => $product->id,
        'warehouse_id' => $warehouse2->id,
        'stock' => 40,
        'min_stock' => 5,
        'aisle_location' => 'Estante B-3',
    ]);

    expect($warehouse->branch->id)->toBe($branch->id)
        ->and($warehouse->products)->toHaveCount(1)
        ->and((float) $warehouse->products->first()->pivot->stock)->toBe(60.0)
        ->and($product->stockInWarehouse($warehouse))->toBe(60.0)
        ->and($product->stockInWarehouse($warehouse2))->toBe(40.0);

    // Sync consolidated stock
    $product->syncConsolidatedStock();
    expect((float) $product->fresh()->stock)->toBe(100.0);
});

